class Solution {
public:
    int medianOfUniquenessArray(vector<int>& nums) {
        int n = nums.size();
        long long total = 1LL * n * (n + 1) / 2;
        long long target = (total + 1) / 2;

        auto count_at_most = [&](int k) {
            unordered_map<int, int> freq;
            int left = 0;
            long long cnt = 0;
            for (int right = 0; right < n; ++right) {
                freq[nums[right]]++;
                while (freq.size() > k) {
                    freq[nums[left]]--;
                    if (freq[nums[left]] == 0) {
                        freq.erase(nums[left]);
                    }
                    left++;
                }
                cnt += (right - left + 1);
            }
            return cnt;
        };

        int low = 1, high = n, ans = n;
        while (low <= high) {
            int mid = low + (high - low) / 2;
            if (count_at_most(mid) >= target) {
                ans = mid;
                high = mid - 1;
            } else {
                low = mid + 1;
            }
        }
        return ans;
    }
};

class Solution {
    public int medianOfUniquenessArray(int[] nums) {
        int n = nums.length;
        long total = (long) n * (n + 1) / 2;
        long target = (total + 1) / 2;

        int low = 1, high = n, ans = n;
        while (low <= high) {
            int mid = low + (high - low) / 2;
            if (countAtMost(nums, mid) >= target) {
                ans = mid;
                high = mid - 1;
            } else {
                low = mid + 1;
            }
        }
        return ans;
    }

    private long countAtMost(int[] nums, int k) {
        Map<Integer, Integer> freq = new HashMap<>();
        int left = 0;
        long cnt = 0;
        for (int right = 0; right < nums.length; right++) {
            freq.put(nums[right], freq.getOrDefault(nums[right], 0) + 1);
            while (freq.size() > k) {
                int count = freq.get(nums[left]) - 1;
                if (count == 0) {
                    freq.remove(nums[left]);
                } else {
                    freq.put(nums[left], count);
                }
                left++;
            }
            cnt += (right - left + 1);
        }
        return cnt;
    }
}

var medianOfUniquenessArray = function(nums) {
    const n = nums.length;
    const total = Math.floor(n * (n + 1) / 2);
    const target = Math.floor((total + 1) / 2);

    function countAtMost(k) {
        const freq = new Map();
        let left = 0;
        let cnt = 0;
        for (let right = 0; right < n; right++) {
            freq.set(nums[right], (freq.get(nums[right]) || 0) + 1);
            while (freq.size > k) {
                const count = freq.get(nums[left]) - 1;
                if (count === 0) {
                    freq.delete(nums[left]);
                } else {
                    freq.set(nums[left], count);
                }
                left++;
            }
            cnt += (right - left + 1);
        }
        return cnt;
    }

    let low = 1, high = n, ans = n;
    while (low <= high) {
        const mid = Math.floor((low + high) / 2);
        if (countAtMost(mid) >= target) {
            ans = mid;
            high = mid - 1;
        } else {
            low = mid + 1;
        }
    }
    return ans;
};
